library(tidyverse)
library(ggrepel)
library(patchwork)


epl2627 &lt;- read_csv("EPL_2026-27.csv.csv") |&gt;
  mutate(season = 2027)

epl2526 &lt;- read_csv("EPL_2025-26.csv.csv")|&gt;
  mutate(season = 2026)

epl2425 &lt;- read_csv("EPL_2024-25.csv.csv")|&gt;
  mutate(season = 2025)

epl2324 &lt;- read_csv("EPL_2023-24.csv.csv")|&gt;
  mutate(season = 2024)

epl2223 &lt;- read_csv("EPL_2022-23.csv.csv")|&gt;
  mutate(season = 2023)

h2223 &lt;- epl2223 |&gt;
  filter(Player == "Erling Haaland") 
h2324 &lt;- epl2324 |&gt;
  filter(Player == "Erling Haaland") 
h2425 &lt;- epl2425 |&gt;
  filter(Player == "Erling Haaland") 
h2526 &lt;- epl2526 |&gt;
  filter(Player == "Erling Haaland") 
h2627 &lt;- epl2627 |&gt;
  filter(Player == "Erling Haaland") 

 hgoals2223 &lt;- ggplot() +
  geom_point(data = epl2223, aes(x=Gls, y=Gls_90)) +
  geom_point(
    data=h2223,
    aes(x=Gls, y=Gls_90),
     color="#6CABDD"
  ) +
   labs(
    x="Goals", 
    y="Goals per 90 minutes", 
    title="2022-23 Season", 
    caption="Source: FBref.com | By Kade Martin"
    ) +
  theme_minimal()

hgoals2324 &lt;- ggplot() +
  geom_point(data = epl2324, aes(x=Gls, y=Gls_90)) +
  geom_point(
    data=h2324,
    aes(x=Gls, y=Gls_90),
     color="#6CABDD"
  ) + 
  labs(
    x="Goals", 
    y="Goals per 90 minutes", 
    title="2023-24 Season", 
    caption="Source: FBref.com | By Kade Martin"
    ) +
  theme_minimal()

 hgoals2425 &lt;- ggplot() +
  geom_point(data = epl2425, aes(x=Gls, y=Gls_90)) +
  geom_point(
    data=h2425,
    aes(x=Gls, y=Gls_90),
     color="#6CABDD"
  ) + 
  labs(
    x="Goals", 
    y="Goals per 90 minutes", 
    title="2024-25 Season", 
    caption="Source: FBref.com | By Kade Martin"
    ) +
  theme_minimal()

  hgoals2526 &lt;- ggplot() +
  geom_point(data = epl2526, aes(x=Gls, y=Gls_90)) +
  geom_point(
    data=h2526,
    aes(x=Gls, y=Gls_90),
     color="#6CABDD"
  ) + 
  labs(
    x="Goals", 
    y="Goals per 90 minutes", 
    title="2025-26 Season", 
    caption="Source: FBref.com | By Kade Martin"
    )  +
  theme_minimal()

  hgoals2627 &lt;- ggplot() +
  geom_point(data = epl2627, aes(x=Gls, y=Gls_90)) +
  geom_point(
    data=h2627,
    aes(x=Gls, y=Gls_90),
     color="#6CABDD"
  ) + 
  labs(
    x="Goals", 
    y="Goals per 90 minutes", 
    title="2026-27 Season", 
    subtitle = "Through Matchweek 8",
    caption="Source: FBref.com | By Kade Martin"
    ) +
  theme_minimal()

hgoals2223 + hgoals2324 / hgoals2425 + hgoals2526 / hgoals2627 +
  plot_annotation(
    title = "Erling Haaland Goals",
    subtitle = "Where does Erling Haaland rank in each season since joining the EPL?", 
    caption="Source: FBref.com | By Kade Martin"
  ) & 
  theme(
    plot.title = element_text(size = 16, face = "bold"),
    axis.title = element_text(size = 8), 
    plot.subtitle = element_text(size=10), 
    panel.grid.minor = element_blank()
  )











